entities:
{
  name: 'page',
  columns: {
    id: {
      type: 'varchar',
      primary: true
    },
    userId: {
      type: 'varchar',
      nullable: true
    },
    date: {
      type: 'date',
      nullable: true
    }
  },
  relations: {
    tags: {
      type: 'one-to-many',
      target: 'pageTag',
      eager: true,
      cascade: true,
      inverseSide: 'page'
    },
    title: {
      type: 'one-to-many',
      target: 'pageTitle',
      eager: true,
      cascade: true,
      inverseSide: 'page'
    },
    body: {
      type: 'one-to-many',
      target: 'pageBody',
      eager: true,
      cascade: true,
      inverseSide: 'page'
    }
  }
}

{
  name: 'pageTag',
  columns: {
    id: {
      type: 'int',
      primary: true,
      generated: true
    },
    name: {
      type: 'varchar'
    },
    start: {
      type: 'date',
      nullable: true
    },
    end: {
      type: 'date',
      nullable: true
    }
  },
  relations: {
    page: {
      type: 'many-to-one',
      target: 'page',
      onDelete: 'CASCADE',
      orphanedRowAction: 'delete',
      inverseSide: 'tags'
    }
  }
}

{
  name: 'pageTitle',
  columns: {
    id: {
      type: 'int',
      primary: true,
      generated: true
    },
    locale: {
      type: 'varchar'
    },
    value: {
      type: 'varchar',
      nullable: true
    }
  },
  relations: {
    page: {
      type: 'many-to-one',
      target: 'page',
      onDelete: 'CASCADE',
      orphanedRowAction: 'delete',
      inverseSide: 'title'
    }
  },
  indices: [
    {
      synchronize: false,
      unique: true,
      columns: ['page', 'locale']
    }
  ]
}

{
  name: 'pageBody',
  columns: {
    id: {
      type: 'int',
      primary: true,
      generated: true
    },
    locale: {
      type: 'varchar'
    },
    value: {
      type: 'text',
      nullable: true
    }
  },
  relations: {
    page: {
      type: 'many-to-one',
      target: 'page',
      onDelete: 'CASCADE',
      orphanedRowAction: 'delete',
      inverseSide: 'body'
    }
  },
  indices: [
    {
      synchronize: false,
      unique: true,
      columns: ['page', 'locale']
    }
  ]
}

format:
{
  ...target,
  title: Object.fromEntries(target.title.map(({locale, value}) => [locale, value])),
  body: Object.fromEntries(target.body.map(({locale, value}) => [locale, value]))
}

contents.options:
((sl, dl) => ({
  select: {
    id: true
  },
  loadEagerRelations: false,
  relations: {
    title: true,
    body: true
  },
  where: {
    id: request.query.id,
    tags: !request.user?.authorized && {
      name: 'PUBLISHED',
      start: Raw(alias => `${alias} is null or ${alias} < :p1`, {p1: new Date()}),
      end: Raw(alias => `${alias} is null or ${alias} > :p2`, {p2: new Date()})
    },
    title: {
      locale: Or(Equal(sl), Equal(dl), IsNull())
    },
    body: {
      locale: Or(Equal(sl), Equal(dl))
    }
  }
}))(system.locale, Object.keys(settings.schema.locales)[0])

contents.projection:
((sl, dl) => ({
  title: target.title.find(({locale}) => locale === sl)?.value || target.title.find(({locale}) => locale === dl)?.value,
  code: transform(target.body.find(({locale}) => locale === sl)?.value || target.body.find(({locale}) => locale === dl)?.value)
}))(system.locale, Object.keys(settings.schema.locales)[0])

contents.options:
((sl, dl) => ({
  select: {
    id: true
  },
  loadEagerRelations: false,
  relations: {
    title: true
  },
  where: {
    tags: {
      name: 'MENU',
      start: Raw(alias => `${alias} is null or ${alias} < :p1`, {p1: new Date()}),
      end: Raw(alias => `${alias} is null or ${alias} > :p2`, {p2: new Date()})
    },
    title: {
      locale: Or(Equal(sl), Equal(dl))
    }
  }
}))(system.locale, Object.keys(settings.schema.locales)[0])

contents.projection:
((sl, dl) => target.map(({id, title}) => ({
  id,
  title: title.find(({locale}) => locale === sl)?.value || title.find(({locale}) => locale === dl)?.value
})))(system.locale, Object.keys(settings.schema.locales)[0])

